dashboard.definition:
{
	"title": "Executive Overview",
	"description": "Summarize secure-networking posture, operational risk, and business-relevant outcomes.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#16283c",
				"strokeColor": "rgba(53,207,245,0.42)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Agentic Ops",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/agentic-ops.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#e8f1fb",
				"markdown": "# Executive Overview\nSummarize secure-networking posture, operational risk, and business-relevant outcomes."
			}
		},
		"viz_overview_ap_health": {
			"type": "splunk.singlevalue",
			"title": "AP Health",
			"dataSources": {
				"primary": "ds_overview_ap_health"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"showSparklineAreaGraph": true,
				"showSparklineTooltip": true,
				"showTrendIndicator": true,
				"sparklineDisplay": "below",
				"sparklineNullValueDisplay": "connect",
				"trendDisplay": "percent",
				"majorColor": "#10b981",
				"majorValue": "> primary | seriesByName('pct') | lastPoint()",
				"unit": "%"
			},
			"description": "Shows what percentage of Catalyst Center access points are reachable at any moment, along with a count of how many are up or down."
		},
		"viz_secure_networking_meraki_ap_count": {
			"type": "splunk.singlevalue",
			"title": "Meraki Access Point Count",
			"dataSources": {
				"primary": "ds_secure_networking_meraki_ap_count"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"showSparklineAreaGraph": true,
				"showSparklineTooltip": true,
				"showTrendIndicator": true,
				"sparklineDisplay": "below",
				"sparklineNullValueDisplay": "connect",
				"trendDisplay": "percent",
				"majorColor": "#2563EB",
				"majorValue": "> primary | seriesByName('ap_count') | lastPoint()"
			},
			"description": "Total count of unique Cisco Meraki access points in the managed wireless infrastructure, providing the wireless footprint KPI."
		},
		"viz_secure_networking_dc_health_signals_trend": {
			"type": "splunk.area",
			"title": "DC Health Signals Trend",
			"dataSources": {
				"primary": "ds_secure_networking_dc_health_signals_trend"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "bottom",
				"seriesColors": [
					"#2563EB",
					"#8bd45b",
					"#ff9a4a",
					"#ff7169"
				],
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"lineWidth": 2,
				"nullValueDisplay": "gaps",
				"dataValuesDisplay": "minmax"
			},
			"description": "Hourly trend combining Cisco Nexus Dashboard anomalies and security advisories as a unified DC health signal, enabling operators to correlate infrastructure health degradation with specific time windows."
		},
		"viz_feed_monitor_all_feeds_health_matrix": {
			"type": "splunk.table",
			"title": "ALL Feeds - Consolidated Health Matrix",
			"dataSources": {
				"primary": "ds_feed_monitor_all_feeds_health_matrix"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Single-pane consolidated health matrix for every critical Cisco data feed - ThousandEyes, FTD, FMC eStreamer, Catalyst Center, SD-WAN, ISE, Cisco Spaces, IOS syslog, Duo, Meraki, Zeek, and ACI/ND."
		},
		"viz_overview_topology_overview": {
			"type": "splunk.table",
			"title": "Topology Overview",
			"dataSources": {
				"primary": "ds_overview_topology_overview"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Overview topology feed - one normalized search that populates topology sites, topology links, and the two right-column KPI cards next to the map. Rows use itemType values of site , link , or summary ."
		},
		"viz_overview_link_auburndale_tallahassee_health": {
			"type": "splunk.table",
			"title": "Link Site 1 to Site 2 Health",
			"dataSources": {
				"primary": "ds_overview_link_auburndale_tallahassee_health"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Site 1 to Site 2 link health — normalized topology-link row for the Overview map. This is the only inter-site link stanza for a two-site footprint."
		},
		"viz_overview_link_state_drilldown": {
			"type": "splunk.table",
			"title": "Link State Drilldown",
			"dataSources": {
				"primary": "ds_overview_link_state_drilldown"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Per-link SD-WAN telemetry snapshot used as the drilldown for the topology link tiles. One row per (device, interface) pair with the latest utilization and a thresholded Stable/Warning/Critical flag."
		},
		"viz_executive_dashboard_ds_device_health_current_drilldown": {
			"type": "splunk.table",
			"title": "Current Device Health Drilldown",
			"dataSources": {
				"primary": "ds_executive_dashboard_ds_device_health_current_drilldown"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Per-device detail roster backing the DEVICE HEALTH tile drilldown. One row per DeviceID with the latest reachability and manageability flags, the 0/50/100 health score the parent tile averages, and the most-recent event…"
		},
		"viz_executive_dashboard_ds_device_health_trend_compare": {
			"type": "splunk.singlevalue",
			"title": "Device Health Trend Comparison",
			"dataSources": {
				"primary": "ds_executive_dashboard_ds_device_health_trend_compare"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"showSparklineAreaGraph": true,
				"showSparklineTooltip": true,
				"showTrendIndicator": true,
				"sparklineDisplay": "below",
				"sparklineNullValueDisplay": "connect",
				"trendDisplay": "percent",
				"majorColor": "#3B82F6",
				"majorValue": "> primary | seriesByName('current') | lastPoint()"
			},
			"description": "Shows the Catalyst Center fleet-average device health trend across automatic time buckets in the selected dashboard range."
		},
		"viz_executive_summary_healthy_device_count": {
			"type": "splunk.singlevalue",
			"title": "Healthy Device Count",
			"dataSources": {
				"primary": "ds_executive_summary_healthy_device_count"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"showSparklineAreaGraph": true,
				"showSparklineTooltip": true,
				"showTrendIndicator": true,
				"sparklineDisplay": "below",
				"sparklineNullValueDisplay": "connect",
				"trendDisplay": "percent",
				"majorColor": "#3B82F6",
				"majorValue": "> primary | seriesByName('healthy_count') | lastPoint()"
			},
			"description": "Supplies the Healthy Devices KPI tile with an absolute count of reachable, managed assets plus the fleet total and percent healthy for quick ratio context."
		},
		"viz_executive_dashboard_data_source_status": {
			"type": "splunk.table",
			"title": "Data Source Status",
			"dataSources": {
				"primary": "ds_executive_dashboard_data_source_status"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Shows which Cisco and IT systems are actively sending data to Splunk and how many events each sent in the last 24 hours. A row appearing here confirms that integration is working — a missing row means that system’s data…"
		},
		"viz_design_context": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "**Audience:** Executives, security leaders, and network leaders  •  **Sources:** Cisco network, security, data-center, and telemetry feeds  •  **Reading guide:** Use KPIs for posture, trends for trajectory, and feed health to judge confidence.  •  **Freshness:** Uses the dashboard time range"
			}
		},
		"viz_design_section": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "### Executive signals\nUse KPIs for posture, trends for trajectory, and feed health to judge confidence."
			}
		}
	},
	"dataSources": {
		"ds_overview_ap_health": {
			"name": "Overview - AP Health",
			"options": {
				"ref": "overview_ap_health",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_secure_networking_meraki_ap_count": {
			"name": "Secure Networking - Meraki Access Point Count",
			"options": {
				"ref": "secure_networking_meraki_ap_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_secure_networking_dc_health_signals_trend": {
			"name": "Secure Networking - DC Health Signals Trend",
			"options": {
				"ref": "secure_networking_dc_health_signals_trend",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_feed_monitor_all_feeds_health_matrix": {
			"name": "Feed Monitor - ALL Feeds - Consolidated Health Matrix",
			"options": {
				"ref": "feed_monitor_all_feeds_health_matrix",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_overview_topology_overview": {
			"name": "Overview - Topology Overview",
			"options": {
				"ref": "overview_topology_overview",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_overview_link_auburndale_tallahassee_health": {
			"name": "Overview - Link Site 1 to Site 2 Health",
			"options": {
				"ref": "overview_link_auburndale_tallahassee_health",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_overview_link_state_drilldown": {
			"name": "Overview - Link State Drilldown",
			"options": {
				"ref": "overview_link_state_drilldown",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_executive_dashboard_ds_device_health_current_drilldown": {
			"name": "Executive - Current Device Health Drilldown",
			"options": {
				"ref": "executive_dashboard_ds_device_health_current_drilldown",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_executive_dashboard_ds_device_health_trend_compare": {
			"name": "Executive - Device Health Trend Comparison",
			"options": {
				"ref": "executive_dashboard_ds_device_health_trend_compare",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_executive_summary_healthy_device_count": {
			"name": "Executive Summary - Healthy Device Count",
			"options": {
				"ref": "executive_summary_healthy_device_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_executive_dashboard_data_source_status": {
			"name": "Executive - Data Source Status",
			"options": {
				"ref": "executive_dashboard_data_source_status",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#07101d",
					"display": "auto-scale",
					"height": 2910,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 118
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 19,
							"w": 80,
							"h": 80
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 132,
							"y": 8,
							"w": 1268,
							"h": 102
						},
						"type": "block"
					},
					{
						"item": "viz_design_context",
						"position": {
							"x": 20,
							"y": 138,
							"w": 1400,
							"h": 92
						},
						"type": "block"
					},
					{
						"item": "viz_design_section",
						"position": {
							"x": 20,
							"y": 250,
							"w": 1400,
							"h": 72
						},
						"type": "block"
					},
					{
						"item": "viz_overview_ap_health",
						"position": {
							"x": 20,
							"y": 342,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_meraki_ap_count",
						"position": {
							"x": 730,
							"y": 342,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_dc_health_signals_trend",
						"position": {
							"x": 20,
							"y": 770,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_feed_monitor_all_feeds_health_matrix",
						"position": {
							"x": 730,
							"y": 770,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_overview_topology_overview",
						"position": {
							"x": 20,
							"y": 1198,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_overview_link_auburndale_tallahassee_health",
						"position": {
							"x": 730,
							"y": 1198,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_overview_link_state_drilldown",
						"position": {
							"x": 20,
							"y": 1626,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_executive_dashboard_ds_device_health_current_drilldown",
						"position": {
							"x": 730,
							"y": 1626,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_executive_dashboard_ds_device_health_trend_compare",
						"position": {
							"x": 20,
							"y": 2054,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_executive_summary_healthy_device_count",
						"position": {
							"x": 730,
							"y": 2054,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_executive_dashboard_data_source_status",
						"position": {
							"x": 20,
							"y": 2482,
							"w": 690,
							"h": 408
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": false,
		"hideExport": false
	}
}
